if.script:
if (!screenPath.startsWith('/')) screenPath = '/' + screenPath
screenPath = screenPath.replaceAll('/apps/', '/qapps/')
curScreenUrl = "https://" + webHostName + screenPath
const parms = bodyParmKeys.map(key => encodeURIComponent(key) + '=' + encodeURIComponent(bodyParameters[key] ?? ''))
if (parms.length) curScreenUrl += '?' + parms.join('&')

render-mode.text:
${title}

<#if curScreenUrl>
${curScreenUrl}

</#if>
<#list bodyParmKeys as parmName>
    <#assign parmValue = bodyParameters[parmName] ?? ''>
    <#if parmValue !== ''>
${parmName}: ${parmValue}
    </#if>
</#list>
